-- Synchronize Costa Rica assistance and emergency institutions from OpenStreetMap.
-- Source: https://www.openstreetmap.org (ODbL-1.0), queried through QLever's OSM Planet dataset.
-- Scope: Costa Rica administrative relation 287667.
-- Coordinates for mapped areas use the first geometry coordinate as a stable representative point.
ON CONFLICT (osm_type, osm_id) WHERE osm_type IS NOT NULL AND osm_id IS NOT NULL
DO UPDATE SET title = EXCLUDED.title, location = EXCLUDED.location, osm_tags = EXCLUDED.osm_tags, data_source = EXCLUDED.data_source, source_license = EXCLUDED.source_license, source_updated_at = EXCLUDED.source_updated_at, imported_at = EXCLUDED.imported_at;

